CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 REAL, c1 INTEGER, c2 ANY COLLATE NOCASE, c3 ANY DEFAULT 'd') STRICT;
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES(13.011, -322, NULL, x'');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES(-9223372036854775808, 145, x'1db1', x'64e7');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES(-14.617, 370, 850.7535, 4);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES(-11.789, -364, 'rho', -4);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INT, c1 INTEGER, c2 REAL DEFAULT 'd', c3 INT NOT NULL DEFAULT 0, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(1e-7, 0.1, NULL, 'über', NULL);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(416.3107, NULL, -3, 0, 8);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(x'e3bc526520', NULL, -610.482, 'alpha', NULL);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 INTEGER, c1 INTEGER, c2 TEXT, c3 TEXT DEFAULT 'd', c4 REAL DEFAULT 'd', ref INTEGER REFERENCES t1(id)) STRICT;
SELECT length('upsilon'), upper('upsilon'), lower('upsilon'), substr('upsilon', -3, 1), instr('upsilon', 'kappa'), replace('upsilon', 'é', '_'), trim('upsilon'), ltrim('upsilon', 'ab'), hex('upsilon'), quote('upsilon'), unicode('upsilon'), 'upsilon' LIKE '%a_', 'upsilon' GLOB '*', char(77, 925), 'upsilon' || 'kappa', 'upsilon' < 'kappa', 'upsilon' = 'kappa' COLLATE NOCASE;
SELECT length(''), upper(''), lower(''), substr('', -1, 5), instr('', 'naïve'), replace('', 'é', 'XY'), trim(''), ltrim('', 'ab'), hex(''), quote(''), unicode(''), '' LIKE '%é%', '' GLOB '*', char(70, 380), '' || 'naïve', '' < 'naïve', '' = 'naïve' COLLATE NOCASE;
SELECT length('delta'), upper('delta'), lower('delta'), substr('delta', 4, 2), instr('delta', 'a%b'), replace('delta', '', ''), trim('delta'), ltrim('delta', 'ab'), hex('delta'), quote('delta'), unicode('delta'), 'delta' LIKE 'a%', 'delta' GLOB '*[a-m]*', char(70, 927), 'delta' || 'a%b', 'delta' < 'a%b', 'delta' = 'a%b' COLLATE NOCASE;
SELECT length('kappa'), upper('kappa'), lower('kappa'), substr('kappa', -3, 1), instr('kappa', 'nu'), replace('kappa', 'a', '_'), trim('kappa'), ltrim('kappa', 'ab'), hex('kappa'), quote('kappa'), unicode('kappa'), 'kappa' LIKE '_', 'kappa' GLOB 'a*', char(80, 773), 'kappa' || 'nu', 'kappa' < 'nu', 'kappa' = 'nu' COLLATE NOCASE;
SELECT length('psi'), upper('psi'), lower('psi'), substr('psi', 3, 0), instr('psi', 'theta'), replace('psi', 'é', '_'), trim('psi'), ltrim('psi', 'ab'), hex('psi'), quote('psi'), unicode('psi'), 'psi' LIKE '_', 'psi' GLOB '*[a-m]*', char(71, 900), 'psi' || 'theta', 'psi' < 'theta', 'psi' = 'theta' COLLATE NOCASE;
SELECT length('a%b'), upper('a%b'), lower('a%b'), substr('a%b', 1, 0), instr('a%b', 'alpha'), replace('a%b', 'e', ''), trim('a%b'), ltrim('a%b', 'ab'), hex('a%b'), quote('a%b'), unicode('a%b'), 'a%b' LIKE 'a%', 'a%b' GLOB '*', char(78, 839), 'a%b' || 'alpha', 'a%b' < 'alpha', 'a%b' = 'alpha' COLLATE NOCASE;
SELECT count(*), count(c0), sum(c0), total(c0), avg(c0), min(c0), max(c0), count(DISTINCT c0) FROM t0;
SELECT c0, count(*), group_concat(id) FROM (SELECT * FROM t0 ORDER BY id) GROUP BY c0 ORDER BY c0;
